const products = db.collection('products');

// Delete one matching document
const r1 = await products.deleteOne({ name: 'Old Widget' });
console.log('Deleted:', r1.deletedCount);  // 0 or 1

// Delete all out-of-stock products
const r2 = await products.deleteMany({ inStock: false });
console.log('Deleted:', r2.deletedCount, 'documents');

// Delete with more complex filter
const oneMonthAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
const r3 = await sessions.deleteMany({
  expiresAt: { $lt: new Date() }  // delete all expired sessions
});

// Delete by ID
const { ObjectId } = require('mongodb');
await products.deleteOne({ _id: new ObjectId('6752ab3f1234567890abcdef') });

// findOneAndDelete — atomically remove and return the document
const deleted = await tasks.findOneAndDelete(
  { status: 'completed' },
  { sort: { completedAt: 1 } }  // remove oldest completed task first
);
if (deleted) console.log('Archived task:', deleted.title);

// Drop a collection — removes all documents AND all indexes
await db.collection('temp_data').drop();

// Drop an entire database — removes all collections and data
await client.db('old_project').dropDatabase();

// Drop is IRREVERSIBLE — no recycle bin, no undo!
// Always back up before dropping in production.

// In mongosh:
db.temp_data.drop()       // drop collection
db.dropDatabase()         // drop current database

// Soft delete: mark as deleted without removing the document
await users.updateOne(
  { _id: userId },
  { $set: { deletedAt: new Date(), deletedBy: adminId } }
);

// In all queries, filter out deleted records
const activeUsers = await users.find({
  deletedAt: { $exists: false }  // only undeleted users
}).toArray();

// Or use $eq: null (works for both missing field and null value)
const activeUsers2 = await users.find({
  deletedAt: null
}).toArray();

// Restore a soft-deleted record
await users.updateOne(
  { _id: userId },
  { $unset: { deletedAt: '', deletedBy: '' } }
);

// Hard delete after retention period (GDPR compliance)
const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
await users.deleteMany({
  deletedAt: { $lt: thirtyDaysAgo }
});

// Create a TTL index: delete sessions 24 hours after createdAt
await sessions.createIndex(
  { createdAt: 1 },
  { expireAfterSeconds: 86400 }  // 86400 seconds = 24 hours
);

// Now just insert normally — MongoDB auto-deletes after 24h
await sessions.insertOne({
  userId: userId,
  token: generateToken(),
  createdAt: new Date()  // TTL field
});

// For exact expiry time, use expiresAt field
await sessions.createIndex(
  { expiresAt: 1 },
  { expireAfterSeconds: 0 }  // expire AT the expiresAt time
);
await sessions.insertOne({
  userId: userId,
  token: generateToken(),
  expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000)  // 7 days from now
});
